import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Allocation } from '@/lib/mockdata';

export function AllocationTable({ allocations }: { allocations: Allocation[] }) {
  return <Card><CardHeader className="flex-row items-end justify-between space-y-0 pb-4"><div><p className="font-mono text-xs uppercase tracking-[0.18em] text-primary">Supply ledger</p><CardTitle className="mt-2 text-lg">Farmer allocations</CardTitle></div><span className="text-xs text-muted-foreground">Production lot traceability</span></CardHeader><CardContent><div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left text-sm"><thead className="border-b border-border/70 text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="pb-3 font-medium">Farmer / lot</th><th className="pb-3 font-medium">Parish</th><th className="pb-3 text-right font-medium">Quantity</th><th className="pb-3 text-right font-medium">Role</th></tr></thead><tbody className="divide-y divide-border/60">{allocations.map((allocation) => <tr key={allocation.id}><td className="py-3"><p className="font-medium">{allocation.farmer}</p><p className="font-mono text-xs text-muted-foreground">{allocation.farmerId} · {allocation.lotId}</p></td><td className="py-3 text-muted-foreground">{allocation.parish}</td><td className="py-3 text-right font-mono">{allocation.quantityKg} kg</td><td className="py-3 text-right"><Badge variant="outline" className={allocation.role === 'STANDBY' ? 'border-warning/40 text-warning' : 'border-success/40 text-success'}>{allocation.role === 'STANDBY' ? 'Standby' : 'Committed'}</Badge></td></tr>)}</tbody></table></div></CardContent></Card>;
}